<script setup>
import { ref } from 'vue';
import { Head, Link, router } from '@inertiajs/vue3';
import AppLayout from '../../Layouts/AppLayout.vue';
import ProductCategoryForm from '../../Components/ProductCategoryForm.vue';
import ProductDeleteDialog from '../../Components/ProductDeleteDialog.vue';
import Dialog from '../../Components/Shared/Dialog.vue';
defineOptions({ layout: AppLayout });
const props = defineProps({ store: Object, products: Object, categories: Array, tab: String, search: String, catalogUrl: String, createUrl: String, categoryStoreUrl: String, overviewUrl: String, storefrontUrl: String });
const deletingProduct = ref(null);
const search = ref(props.search);
const editingCategory = ref(null);
const showCategoryForm = ref(false);
const editCategory = (category) => { editingCategory.value = category; showCategoryForm.value = true; };
const filter = () => router.get(props.catalogUrl, { search: search.value }, { preserveState: true, replace: true });
const money = (amount) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(amount);
</script>

<template>
    <Head :title="`${store.name} — Catalog`" />
    <Link :href="overviewUrl" class="text-sm text-stone-500 hover:underline">← Store overview</Link>
    <div class="mt-5 flex flex-wrap justify-between gap-5"><div><p class="text-xs font-medium text-stone-500">{{ store.name }}</p><h1 class="mt-2 text-3xl font-semibold tracking-tight">Your catalog</h1><p class="mt-3 text-stone-500">Manage your products. Saved products appear in your public catalog automatically.</p></div><Link :href="storefrontUrl" class="self-start rounded-full border border-stone-300 px-5 py-3 text-sm">Preview store ↗</Link></div>
    <nav aria-label="Catalog sections" class="mt-8 flex gap-3 border-b border-stone-200 pb-3"><Link :href="catalogUrl" :aria-current="tab === 'products' ? 'page' : undefined" :class="tab === 'products' ? 'bg-[#504941] text-white' : 'text-stone-500 hover:bg-stone-100'" class="rounded-xl px-5 py-2.5 text-sm font-medium">Products</Link><Link :href="`${catalogUrl}?tab=categories`" :aria-current="tab === 'categories' ? 'page' : undefined" :class="tab === 'categories' ? 'bg-[#504941] text-white' : 'text-stone-500 hover:bg-stone-100'" class="rounded-xl px-5 py-2.5 text-sm font-medium">Categories</Link></nav>
    <section v-if="tab === 'products'" class="mt-7">
        <div class="flex flex-wrap items-center justify-between gap-4"><form class="flex min-w-0 max-w-md flex-1 gap-2" @submit.prevent="filter"><label for="catalog-search" class="sr-only">Search your products</label><input id="catalog-search" v-model="search" type="search" maxlength="100" placeholder="Search products" class="min-w-0 flex-1 rounded-xl border border-stone-300 bg-white px-4 py-3"><button class="rounded-xl border border-stone-300 px-4 py-3 text-sm">Search</button></form><Link v-if="categories.length" :href="createUrl" class="rounded-xl bg-[#504941] px-5 py-3 text-sm font-medium text-white">Add product</Link><Link v-else :href="`${catalogUrl}?tab=categories`" class="rounded-xl bg-[#504941] px-5 py-3 text-sm font-medium text-white">Create your first category</Link></div>
        <div class="mt-5 overflow-x-auto rounded-2xl border border-stone-200 bg-[#fffdf9]"><table class="w-full min-w-[650px] text-left text-sm"><caption class="sr-only">Products belonging to {{ store.name }}</caption><thead class="border-b border-stone-200 bg-stone-50 text-xs text-stone-500 uppercase"><tr><th scope="col" class="px-5 py-4">Product</th><th scope="col" class="px-5 py-4">Category</th><th scope="col" class="px-5 py-4">Base price</th><th scope="col" class="px-5 py-4">Catalog</th><th scope="col" class="px-5 py-4"><span class="sr-only">Action</span></th></tr></thead><tbody class="divide-y divide-stone-100"><tr v-for="product in products.data" :key="product.id"><th scope="row" class="px-5 py-4"><div class="flex items-center gap-3"><img v-if="product.imageUrl" :src="product.imageUrl" alt="" class="size-12 rounded-xl object-cover"><span v-else aria-hidden="true" class="flex size-12 shrink-0 items-center justify-center rounded-xl bg-[#eee9df] font-medium text-stone-400">{{ product.name.slice(0, 1) }}</span><span class="font-medium">{{ product.name }}</span></div></th><td class="px-5 py-4 text-stone-500">{{ product.category }}</td><td class="px-5 py-4 whitespace-nowrap">{{ money(product.price) }}</td><td class="px-5 py-4"><span class="rounded-full px-2.5 py-1 text-xs" :class="product.is_visible ? 'bg-green-50 text-green-800' : 'bg-stone-100 text-stone-500'">{{ product.is_visible ? 'Visible' : 'Hidden' }}</span></td><td class="px-5 py-4"><div class="flex items-center gap-2"><span v-if="product.isLocked" class="rounded-full bg-amber-50 px-3 py-2 text-xs font-medium text-amber-800" title="Available to edit after the open-order session ends">Locked during open order</span><Link v-else :href="product.editUrl" class="rounded-lg border border-stone-300 px-3 py-2 text-sm font-medium hover:bg-stone-100" :aria-label="`Edit ${product.name}`">Edit</Link><button v-if="!product.isLocked" type="button" class="rounded-lg border border-red-200 px-3 py-2 text-sm font-medium text-red-700 hover:bg-red-50" :aria-label="`Delete ${product.name}`" @click="deletingProduct = product">Delete</button></div></td></tr><tr v-if="!products.data.length"><td colspan="5" class="px-5 py-12 text-center text-stone-500">{{ search ? 'No matching products.' : 'No products yet. Add a category, then your first product.' }}</td></tr></tbody></table></div>
        <nav v-if="products.prev_page_url || products.next_page_url" aria-label="Catalog pagination" class="mt-5 flex justify-between text-sm"><Link v-if="products.prev_page_url" :href="products.prev_page_url" class="underline">← Previous</Link><span v-else /><Link v-if="products.next_page_url" :href="products.next_page_url" class="underline">Next →</Link></nav>
        <p class="mt-6 text-sm leading-7 text-stone-500">Products appear in Our Products automatically, without prices. Create sales sessions in Open orders. Customer checkout is not available yet.</p>
    </section>
    <section v-else class="mt-7"><div class="flex flex-wrap items-center justify-between gap-4"><div><h2 class="text-xl font-semibold">Product categories</h2><p class="mt-2 text-sm text-stone-500">Organize items within your store, for example Coffee and Non-Coffee.</p></div><button type="button" class="rounded-xl bg-[#504941] px-5 py-3 text-sm font-medium text-white" @click="editCategory(null)">Add category</button></div><div class="mt-5 overflow-x-auto rounded-2xl border border-stone-200 bg-[#fffdf9]"><table class="w-full text-left text-sm"><thead class="border-b border-stone-200 bg-stone-50 text-xs text-stone-500 uppercase"><tr><th scope="col" class="px-5 py-4">Category</th><th scope="col" class="px-5 py-4">Products</th><th scope="col" class="px-5 py-4"><span class="sr-only">Action</span></th></tr></thead><tbody class="divide-y divide-stone-100"><tr v-for="category in categories" :key="category.id"><th scope="row" class="px-5 py-4 font-medium">{{ category.name }}</th><td class="px-5 py-4">{{ category.products_count }}</td><td class="px-5 py-4 text-right"><button type="button" :aria-label="`Edit ${category.name}`" class="font-medium underline underline-offset-4" @click="editCategory(category)">Edit</button></td></tr><tr v-if="!categories.length"><td colspan="3" class="px-5 py-10 text-center text-stone-500">Create a category to start adding products.</td></tr></tbody></table></div><Dialog :open="showCategoryForm" :title="editingCategory ? 'Edit category' : 'New category'" @close="showCategoryForm = false"><ProductCategoryForm v-if="showCategoryForm" :key="editingCategory?.id ?? 'new'" :category="editingCategory" :store-url="categoryStoreUrl" @saved="showCategoryForm = false" /></Dialog></section>
    <ProductDeleteDialog :open="Boolean(deletingProduct)" :name="deletingProduct?.name" :url="deletingProduct?.deleteUrl" @close="deletingProduct = null" />
</template>
